## 2. より堅牢な認証ミドルウェア

```javascript
const jwt = require('jsonwebtoken');
const Redis = require('redis'); // ブラックリスト用（オプション）

class AuthMiddleware {
    constructor(options = {}) {
        this.secretKey = options.secretKey || process.env.JWT_SECRET;
        this.redisClient = options.redisClient; // ブラックリスト用
        this.clockTolerance = options.clockTolerance || 30; // 30秒の許容範囲
    }

    authenticate = async (req, res, next) => {
        try {
            const token = this.extractToken(req);

            if (!token) {
                return res.status(401).json({
                    error: 'MISSING_TOKEN',
                    message: 'Authentication token is required'
                });
            }

            // ブラックリストチェック（オプション）
            if (await this.isTokenBlacklisted(token)) {
                return res.status(401).json({
                    error: 'TOKEN_REVOKED',
                    message: 'Token has been revoked'
                });
            }

            const decoded = await this.verifyToken(token);
            req.user = decoded;
            req.token = token;

            next();
        } catch (error) {
            this.handleAuthError(error, res);
        }
    }

    extractToken(req) {
        // Authorization ヘッダーから取得
        const authHeader = req.headers['authorization'];
        if (authHeader && authHeader.startsWith('Bearer ')) {
            return authHeader.slice(7);
        }

        // クエリパラメータから取得（オプション）
        if (req.query.token) {
            return req.query.token;
        }

        // Cookie から取得（オプション）
        if (req.cookies && req.cookies.token) {
            return req.cookies.token;
        }

        return null;
    }

    async verifyToken(token) {
        return new Promise((resolve, reject) => {
            jwt.verify(token, this.secretKey, {
                clockTolerance: this.clockTolerance,
                algorithms: ['HS256', 'HS384', 'HS512'] // 許可するアルゴリズムを明示
            }, (err, decoded) => {
                if (err) {
                    reject(err);
                } else {
                    // 追加のカスタムバリデーション
                    this.validateTokenPayload(decoded);
                    resolve(decoded);
                }
            });
        });
    }

    validateTokenPayload(decoded) {
        // 必須フィールドの存在確認
        if (!decoded.sub && !decoded.userId) {
            throw new Error('Token missing user identifier');
        }

        // トークンタイプの確認
        if (decoded.type && decoded.type !== 'access') {
            throw new Error('Invalid token type');
        }

        // 発行者の確認
        if (decoded.iss && decoded.iss !== process.env.JWT_ISSUER) {
            throw new Error('Invalid token issuer');
        }
    }

    async isTokenBlacklisted(token) {
        if (!this.redisClient) return false;

        try {
            const result = await this.redisClient.get(`blacklist:${token}`);
            return result !== null;
        } catch (error) {
            console.error('Redis error:', error);
            return false; // Redis エラー時はブラックリストチェックをスキップ
        }
    }

    handleAuthError(error, res) {
        console.error('Authentication error:', error);

        switch (error.name) {
            case 'TokenExpiredError':
                return res.status(401).json({
                    error: 'TOKEN_EXPIRED',
                    message: 'Token has expired',
                    expiredAt: error.expiredAt
                });

            case 'JsonWebTokenError':
                return res.status(401).json({
                    error: 'INVALID_TOKEN',
                    message: 'Token is malformed or invalid'
                });

            case 'NotBeforeError':
                return res.status(401).json({
                    error: 'TOKEN_NOT_ACTIVE',
                    message: 'Token not active yet',
                    activeAt: error.date
                });

            default:
                return res.status(401).json({
                    error: 'AUTHENTICATION_FAILED',
                    message: 'Authentication failed'
                });
        }
    }
}

// 使用例
const authMiddleware = new AuthMiddleware({
    secretKey: process.env.JWT_SECRET,
    clockTolerance: 30
});

// Express での使用
app.use('/api/protected', authMiddleware.authenticate);
```

## 3. TypeScript版（型安全性向上）

```typescript
import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';

interface TokenPayload {
    sub?: string;
    userId?: string;
    email?: string;
    role?: string;
    type?: 'access' | 'refresh';
    iss?: string;
    aud?: string;
    exp: number;
    iat: number;
    nbf?: number;
}

interface AuthenticatedRequest extends Request {
    user?: TokenPayload;
    token?: string;
}

export class AuthenticationMiddleware {
    private readonly secretKey: string;
    private readonly clockTolerance: number;

    constructor(secretKey: string, clockTolerance = 30) {
        this.secretKey = secretKey;
        this.clockTolerance = clockTolerance;
    }

    authenticate = (req: AuthenticatedRequest, res: Response, next: NextFunction): void => {
        const token = this.extractToken(req);

        if (!token) {
            res.status(401).json({
                error: 'MISSING_TOKEN',
                message: 'Authentication token is required'
            });
            return;
        }

        jwt.verify(token, this.secretKey, {
            clockTolerance: this.clockTolerance,
            algorithms: ['HS256']
        }, (err: jwt.VerifyErrors | null, decoded: any) => {
            if (err) {
                this.handleVerificationError(err, res);
                return;
            }

            const payload = decoded as TokenPayload;

            // 追加バリデーション
            if (!this.isValidPayload(payload)) {
                res.status(401).json({
                    error: 'INVALID_PAYLOAD',
                    message: 'Token payload is invalid'
                });
                return;
            }

            req.user = payload;
            req.token = token;
            next();
        });
    }

    private extractToken(req: Request): string | null {
        const authHeader = req.headers.authorization;

        if (authHeader?.startsWith('Bearer ')) {
            return authHeader.slice(7);
        }

        return null;
    }

    private isValidPayload(payload: TokenPayload): boolean {
        // ユーザー識別子の存在確認
        if (!payload.sub && !payload.userId) {
            return false;
        }

        // 必要に応じて他のバリデーションを追加
        return true;
    }

    private handleVerificationError(error: jwt.VerifyErrors, res: Response): void {
        switch (error.name) {
            case 'TokenExpiredError':
                res.status(401).json({
                    error: 'TOKEN_EXPIRED',
                    message: 'Token has expired',
                    expiredAt: (error as jwt.TokenExpiredError).expiredAt
                });
                break;

            case 'JsonWebTokenError':
                res.status(401).json({
                    error: 'INVALID_TOKEN',
                    message: 'Token is invalid'
                });
                break;

            case 'NotBeforeError':
                res.status(401).json({
                    error: 'TOKEN_NOT_ACTIVE',
                    message: 'Token is not active yet'
                });
                break;

            default:
                res.status(401).json({
                    error: 'VERIFICATION_FAILED',
                    message: 'Token verification failed'
                });
        }
    }
}
```

## 主な修正点

1. **時間単位の統一**: ミリ秒とUnixタイムスタンプ（秒）の混同を修正
2. **エラーハンドリングの改善**: より詳細で適切なエラーレスポンス
3. **型安全性の向上**: TypeScriptでの型定義
4. **セキュリティの強化**: アルゴリズムの明示、ペイロードバリデーション
5. **柔軟性の向上**: 設定可能なオプション、複数のトークン取得方法

この修正版を参考に、具体的なバグの詳細を教えていただければ、より特定的な修正提案ができます。

