Node.jsでPostgreSQLのコネクションプーリングをセットアップする方法をご説明いたします。

## 1. 必要なパッケージのインストール

まず、`pg`パッケージをインストールします：

```bash
npm install pg
```

TypeScriptを使用する場合は型定義も追加：
```bash
npm install @types/pg
```

## 2. 基本的なコネクションプールの設定

```javascript
const { Pool } = require('pg');

// コネクションプールの作成
const pool = new Pool({
  user: 'your_username',
  host: 'localhost',
  database: 'your_database',
  password: 'your_password',
  port: 5432,

  // プール設定
  max: 20,        // 最大コネクション数
  min: 5,         // 最小コネクション数
  idle: 10000,    // アイドルタイムアウト（ミリ秒）
  evict: 1000,    // 無効なコネクションのチェック間隔
  create: 2000,   // コネクション作成タイムアウト
  destroy: 5000,  // コネクション破棄タイムアウト
  acquire: 60000, // コネクション取得タイムアウト
});
```

## 3. 実際の使用例

### 基本的なクエリの実行

```javascript
async function getAllUsers() {
  const client = await pool.connect();

  try {
    const result = await client.query('SELECT * FROM users');
    return result.rows;
  } finally {
    // 必ずコネクションをプールに戻す
    client.release();
  }
}

// より簡潔な書き方（pool.queryを使用）
async function getUser(id) {
  try {
    const result = await pool.query('SELECT * FROM users WHERE id = $1', [id]);
    return result.rows[0];
  } catch (error) {
    console.error('クエリエラー:', error);
    throw error;
  }
}
```

### トランザクションの使用

```javascript
async function transferMoney(fromUserId, toUserId, amount) {
  const client = await pool.connect();

  try {
    await client.query('BEGIN');

    // 送金者の残高を減らす
    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE user_id = $2',
      [amount, fromUserId]
    );

    // 受取者の残高を増やす
    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE user_id = $2',
      [amount, toUserId]
    );

    await client.query('COMMIT');
    console.log('送金が完了しました');
  } catch (error) {
    await client.query('ROLLBACK');
    console.error('送金エラー:', error);
    throw error;
  } finally {
    client.release();
  }
}
```

## 4. 設定ファイルを使った管理

### config/database.js

```javascript
require('dotenv').config();

const config = {
  development: {
    user: process.env.DB_USER,
    host: process.env.DB_HOST,
    database: process.env.DB_NAME,
    password: process.env.DB_PASSWORD,
    port: process.env.DB_PORT || 5432,
    max: 10,
    idle: 30000,
    acquire: 60000,
  },
  production: {
    connectionString: process.env.DATABASE_URL,
    max: 50,
    idle: 30000,
    acquire: 60000,
    ssl: {
      rejectUnauthorized: false
    }
  }
};

module.exports = config[process.env.NODE_ENV || 'development'];
```

### .env ファイル

```env
DB_USER=postgres
DB_HOST=localhost
DB_NAME=myapp
DB_PASSWORD=your_password
DB_PORT=5432
NODE_ENV=development
```

## 5. データベースクラスの作成

```javascript
const { Pool } = require('pg');
const config = require('./config/database');

class Database {
  constructor() {
    this.pool = new Pool(config);

    // プールイベントの監視
    this.pool.on('connect', () => {
      console.log('新しいコネクションが作成されました');
    });

    this.pool.on('error', (err) => {
      console.error('プールエラー:', err);
    });
  }

  async query(text, params) {
    const start = Date.now();
    try {
      const res = await this.pool.query(text, params);
      const duration = Date.now() - start;
      console.log('実行済みクエリ:', { text, duration, rows: res.rowCount });
      return res;
    } catch (error) {
      console.error('クエリエラー:', error);
      throw error;
    }
  }

  async getClient() {
    const client = await this.pool.connect();
    const query = client.query;
    const release = client.release;

    // タイムアウト処理
    const timeout = setTimeout(() => {
      console.error('クライアントがチェックアウトされたままです');
    }, 5000);

    // releaseをオーバーライドしてタイムアウトをクリア
    client.release = () => {
      clearTimeout(timeout);
      client.release = release;
      return release.apply(client);
    };

    return client;
  }

  async close() {
    await this.pool.end();
    console.log('プールが閉じられました');
  }
}

module.exports = new Database();
```

## 6. Express.jsとの統合例

```javascript
const express = require('express');
const db = require('./database');

const app = express();
app.use(express.json());

app.get('/users', async (req, res) => {
  try {
    const result = await db.query('SELECT * FROM users');
    res.json(result.rows);
  } catch (error) {
    res.status(500).json({ error: 'データベースエラー' });
  }
});

app.post('/users', async (req, res) => {
  const { name, email } = req.body;
  try {
    const result = await db.query(
      'INSERT INTO users (name, email) VALUES ($1, $2) RETURNING *',
      [name, email]
    );
    res.status(201).json(result.rows[0]);
  } catch (error) {
    res.status(500).json({ error: 'ユーザー作成エラー' });
  }
});

// アプリケーション終了時の処理
process.on('SIGINT', async () => {
  console.log('アプリケーションを終了します...');
  await db.close();
  process.exit(0);
});

app.listen(3000, () => {
  console.log('サーバーがポート3000で起動しました');
});
```

## 7. パフォーマンスの監視

```javascript
// プールの状態を監視する関数
function monitorPool(pool) {
  setInterval(() => {
    console.log('プール状態:', {
      totalCount: pool.totalCount,
      idleCount: pool.idleCount,
      waitingCount: pool.waitingCount
    });
  }, 30000); // 30秒ごと
}

monitorPool(pool);
```

これらの設定により、効率的で信頼性の高いPostgreSQLコネクションプーリングをNode.jsアプリケーションで実装できます。プール設定は、アプリケーションの負荷や要件に応じて調整してください。

