}
```

## 6. Express.jsアプリケーションでの使用例

```javascript
const express = require('express');
const { Pool } = require('pg');

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idle: 10000,
  acquire: 60000,
});

// ルート例
app.get('/users', async (req, res) => {
  try {
    const result = await pool.query('SELECT * FROM users');
    res.json(result.rows);
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.post('/users', async (req, res) => {
  const { name, email } = req.body;

  try {
    const result = await pool.query(
      'INSERT INTO users (name, email) VALUES ($1, $2) RETURNING *',
      [name, email]
    );
    res.status(201).json(result.rows[0]);
  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Failed to create user' });
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

## 7. 接続プールの監視とエラーハンドリング

```javascript
// プールのイベントリスナー
pool.on('connect', (client) => {
  console.log('New client connected to the pool');
});

pool.on('error', (err) => {
  console.error('Unexpected error on idle client:', err);
  // 必要に応じて再起動やアラート送信を実装
});

pool.on('remove', (client) => {
  console.log('Client removed from pool');
});

// アプリケーション終了時のクリーンアップ
process.on('SIGINT', async () => {
  console.log('Closing database connections...');
  await pool.end();
  process.exit(0);
});
```

## 8. TypeScript版の実装例

```typescript
import { Pool, PoolClient, QueryResult } from 'pg';

interface User {
  id: number;
  name: string;
  email: string;
  created_at: Date;
}

class Database {
  private pool: Pool;

  constructor() {
    this.pool = new Pool({
      user: process.env.DB_USER,
      host: process.env.DB_HOST,
      database: process.env.DB_DATABASE,
      password: process.env.DB_PASSWORD,
      port: Number(process.env.DB_PORT),
      max: 20,
      idle: 10000,
      acquire: 60000,
    });
  }

  async query<T = any>(text: string, params?: any[]): Promise<QueryResult<T>> {
    return this.pool.query<T>(text, params);
  }

  async getUsers(): Promise<User[]> {
    const result = await this.query<User>('SELECT * FROM users');
    return result.rows;
  }

  async close(): Promise<void> {
    await this.pool.end();
  }
}

export const db = new Database();
```

## 主要なポイント

1. **接続プール設定**: `max`、`idle`、`acquire`パラメータを適切に設定
2. **エラーハンドリング**: 必ずtry-catch文でエラーを処理
3. **接続の解放**: トランザクション使用時は`client.release()`を確実に実行
4. **環境変数**: 認証情報は環境変数で管理
5. **監視**: プールイベントを監視してトラブルシューティングに活用

この設定により、Node.jsアプリケーションで効率的にPostgreSQLとの接続を管理できます。

