## pg パッケージ使用

```javascript
const { Pool } = require('pg');

// プール作成
const pool = new Pool({
  user: 'username',
  host: 'localhost', 
  database: 'dbname',
  password: 'password',
  port: 5432,
  max: 20,        // 最大接続数
  min: 5,         // 最小接続数  
