  acquire: 60000  // 取得タイムアウト
});

// 使用例
async function getUser(id) {
  const client = await pool.connect();
  try {
    const result = await client.query('SELECT * FROM users WHERE id = $1', [id]);
    return result.rows[0];
  } finally {
    client.release(); // 必須: プールに戻す
  }
}

// 簡単クエリ (推奨)
async function getUserSimple(id) {
  const result = await pool.query('SELECT * FROM users WHERE id = $1', [id]);
  return result.rows[0];
}
```

## 理由

- 新接続 = 遅い (ハンドシェイク時間)
- プール = 再利用 → 高速
- 接続数制限 → DB保護

## 設定パラメータ

```javascript
{
  max: 20,        // 同時最大接続
  min: 5,         // 常時保持数
  idle: 10000,    // 10秒未使用で切断
  acquire: 60000, // 60秒で取得タイムアウト
  evict: 1000     // チェック間隔
}
```

`client.release()` 忘れ = 接続リーク → 枯渇。`pool.query()` 使えば自動管理。

