normal_texts:
コールバック地獄をasync/awaitにリファクタリングする方法を説明します。

## Before: コールバック地獄の例

```javascript
// コールバック地獄の典型例
function fetchUserData(userId, callback) {
    getUserInfo(userId, (err, user) => {
        if (err) {
            callback(err, null);
            return;
        }

        getUserPosts(user.id, (err, posts) => {
            if (err) {
                callback(err, null);
                return;
            }

            getPostComments(posts[0].id, (err, comments) => {
                if (err) {
                    callback(err, null);
                    return;
                }

                getUserFriends(user.id, (err, friends) => {
                    if (err) {
                        callback(err, null);
                        return;
                    }

                    // さらにネストが続く...
                    callback(null, {
                        user,
                        posts,
                        comments,
                        friends
                    });
                });
            });
        });
    });
}
