- 読みやすい同期的なコード
- エラーハンドリングが簡潔
- ネストが深くならない
- デバッグしやすい

caveman_texts:
コールバック地獄 → async/await変換。

**Before (地獄):**
```javascript
getData(id, function(err, data) {
  if (err) throw err;
  processData(data, function(err, processed) {
    if (err) throw err;
    saveData(processed, function(err, result) {
      if (err) throw err;
      console.log('完了:', result);
    });
  });
});
```

**After (救済):**
```javascript
async function handleData(id) {
  try {
    const data = await getData(id);
    const processed = await processData(data);  
    const result = await saveData(processed);
    console.log('完了:', result);
  } catch (err) {
    console.error('エラー:', err);
  }
}
```

**元関数をPromise化必要:**
```javascript
// util.promisify使用
const { promisify } = require('util');
const getDataAsync = promisify(getData);
const processDataAsync = promisify(processData);
const saveDataAsync = promisify(saveData);

// または手動wrap
function getData(id) {
  return new Promise((resolve, reject) => {
    oldGetData(id, (err, data) => {
      err ? reject(err) : resolve(data);
    });
  });
}
```

**並列実行なら:**
```javascript
// 順次実行
const [user, posts, comments] = await Promise.all([
  getUser(id),
  getPosts(id), 
  getComments(id)
]);
```

エラーハンドリング一箇所。可読性大幅改善。

コールバック地獄 → async/await変換。

**Before:**
```javascript
function getData(callback) {
  fetchUser(userId, (err, user) => {
    if (err) return callback(err);
    fetchPosts(user.id, (err, posts) => {
      if (err) return callback(err);
      fetchComments(posts[0].id, (err, comments) => {
        if (err) return callback(err);
        callback(null, { user, posts, comments });
      });
    });
  });
}
```

**After:**
```javascript
async function getData() {
  try {
    const user = await fetchUser(userId);
    const posts = await fetchPosts(user.id);
    const comments = await fetchComments(posts[0].id);
    return { user, posts, comments };
  } catch (err) {
    throw err;
  }
}
```

**並列実行なら:**
```javascript
async function getData() {
  const user = await fetchUser(userId);
  const [posts, profile] = await Promise.all([
    fetchPosts(user.id),
    fetchProfile(user.id)
  ]);
  return { user, posts, profile };
}
```

**呼び出し:**
```javascript
// callback版
getData((err, result) => {
  if (err) console.error(err);
  else console.log(result);
});

// async版
try {
  const result = await getData();
  console.log(result);
} catch (err) {
  console.error(err);
}
```

メリット: 読みやすい。エラー処理統一。デバッグ簡単。

コールバック地獄 → async/await変換。

**Before (地獄):**
```javascript
function getUserData(userId, callback) {
  getUser(userId, (err, user) => {
    if (err) return callback(err);

    getProfile(user.id, (err, profile) => {
      if (err) return callback(err);

      getPosts(user.id, (err, posts) => {
        if (err) return callback(err);

        callback(null, { user, profile, posts });
      });
    });
  });
}
```

**After (きれい):**
```javascript
async function getUserData(userId) {
  const user = await getUser(userId);
  const profile = await getProfile(user.id);
  const posts = await getPosts(user.id);

  return { user, profile, posts };
}
```

**並列実行で高速化:**
```javascript
async function getUserData(userId) {
  const user = await getUser(userId);

  // profileとposts同時取得
  const [profile, posts] = await Promise.all([
    getProfile(user.id),
    getPosts(user.id)
  ]);

  return { user, profile, posts };
}
```

**エラーハンドリング:**
```javascript
async function getUserData(userId) {
  try {
    const user = await getUser(userId);
    const [profile, posts] = await Promise.all([
      getProfile(user.id),
      getPosts(user.id)
    ]);

    return { user, profile, posts };
  } catch (error) {
    throw new Error(`ユーザーデータ取得失敗: ${error.message}`);
  }
}
```

使用:
```javascript
