ReactのError Boundaryの実装方法をいくつかのパターンで説明します。

## 1. 基本的なClass Component版Error Boundary

```jsx
import React from 'react';

class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { 
      hasError: false, 
      error: null,
      errorInfo: null 
    };
  }

  static getDerivedStateFromError(error) {
    // エラーが発生したときにstateを更新
    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    // エラー情報をログに記録
    console.error('Error Boundary caught an error:', error, errorInfo);

    this.setState({
      error: error,
      errorInfo: errorInfo
    });

    // ここでエラー監視サービス（Sentry等）にレポートすることも可能
    // logErrorToMyService(error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      // フォールバックUI
      return (
        <div className="error-boundary">
          <h2>申し訳ございません。予期しないエラーが発生しました。</h2>
          <details style={{ whiteSpace: 'pre-wrap' }}>
            <summary>エラー詳細（開発用）</summary>
            <p>{this.state.error && this.state.error.toString()}</p>
            <p>{this.state.errorInfo.componentStack}</p>
          </details>
          <button onClick={() => window.location.reload()}>
            ページを再読み込み
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}
```

## 2. より高機能なError Boundary

```jsx
import React from 'react';

class AdvancedErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      hasError: false,
      error: null,
      errorInfo: null,
      retryCount: 0
    };
  }

  static getDerivedStateFromError(error) {
    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    console.error('Error Boundary caught an error:', error, errorInfo);

    this.setState({
      error: error,
      errorInfo: errorInfo
    });

    // カスタムエラーレポート関数
    this.reportError(error, errorInfo);
  }

  reportError = (error, errorInfo) => {
    // エラー監視サービスへの送信
    if (this.props.onError) {
      this.props.onError(error, errorInfo);
    }
  };

  handleRetry = () => {
    this.setState(prevState => ({
      hasError: false,
      error: null,
      errorInfo: null,
      retryCount: prevState.retryCount + 1
    }));
  };

  render() {
    if (this.state.hasError) {
      // カスタムフォールバックUIがあれば使用
      if (this.props.fallback) {
        return this.props.fallback({
          error: this.state.error,
          retry: this.handleRetry,
          retryCount: this.state.retryCount
        });
      }

      // デフォルトフォールバックUI
      return (
        <div className="error-boundary-container">
          <div className="error-boundary-content">
            <h2>🚨 エラーが発生しました</h2>
            <p>申し訳ございません。アプリケーションでエラーが発生しました。</p>

            {process.env.NODE_ENV === 'development' && (
              <details className="error-details">
                <summary>開発者向け情報</summary>
                <pre>{this.state.error?.toString()}</pre>
                <pre>{this.state.errorInfo?.componentStack}</pre>
              </details>
            )}

            <div className="error-actions">
              <button onClick={this.handleRetry} className="retry-button">
                再試行 ({this.state.retryCount > 0 && `${this.state.retryCount}回目`})
              </button>
              <button onClick={() => window.location.reload()} className="reload-button">
                ページを再読み込み
              </button>
            </div>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}
```

## 3. Hooks版Error Boundary（カスタムフック使用）

```jsx
import React, { useState, useEffect } from 'react';

// Error Boundaryはclass componentでしか実装できないため、
// hooksでエラーハンドリングをするためのカスタムフック
export const useErrorHandler = () => {
  const [error, setError] = useState(null);

  useEffect(() => {
    if (error) {
      throw error;
    }
  }, [error]);

  const resetError = () => setError(null);
  const captureError = (error) => setError(error);

  return { captureError, resetError };
};

// Function Component用のError Boundary Wrapper
export const withErrorBoundary = (Component, errorBoundaryProps = {}) => {
  const WrappedComponent = (props) => (
    <AdvancedErrorBoundary {...errorBoundaryProps}>
      <Component {...props} />
    </AdvancedErrorBoundary>
  );

  WrappedComponent.displayName = `withErrorBoundary(${Component.displayName || Component.name})`;
  return WrappedComponent;
};
```

## 4. 使用例

```jsx
import React, { useState } from 'react';

// エラーを発生させるテストコンポーネント
const ProblematicComponent = () => {
  const [shouldThrow, setShouldThrow] = useState(false);

  if (shouldThrow) {
    throw new Error('意図的に発生させたテストエラー');
  }

  return (
    <div>
      <h3>正常なコンポーネント</h3>
      <button onClick={() => setShouldThrow(true)}>
        エラーを発生させる
      </button>
    </div>
  );
};

// アプリケーション全体
const App = () => {
  return (
    <div>
      <h1>Error Boundary デモ</h1>

      {/* 基本的な使用方法 */}
      <ErrorBoundary>
        <ProblematicComponent />
      </ErrorBoundary>

      {/* カスタムフォールバックUIを使用 */}
      <AdvancedErrorBoundary
        fallback={({ error, retry, retryCount }) => (
          <div style={{ padding: '20px', border: '2px solid red' }}>
            <h3>カスタムエラーUI</h3>
            <p>エラー: {error?.message}</p>
            <button onClick={retry}>
              再試行 (試行回数: {retryCount})
            </button>
          </div>
        )}
        onError={(error, errorInfo) => {
          console.log('カスタムエラーハンドラ:', error);
        }}
      >
        <ProblematicComponent />
      </AdvancedErrorBoundary>

      {/* HOCを使用した場合 */}
      {React.createElement(
        withErrorBoundary(ProblematicComponent, {
          fallback: ({ error, retry }) => (
            <div>
              <p>HOC経由でラップされたエラー</p>
              <button onClick={retry}>再試行</button>
            </div>
          )
        })
      )}
    </div>
  );
};

export default App;
```

