## 重要なポイント

1. **Error Boundaryはclass componentでしか実装できません**
2. **以下のエラーはキャッチできません**：
   - イベントハンドラー内のエラー
   - 非同期コード（setTimeout、Promise等）
   - SSR中のエラー
   - Error Boundary自体のエラー

3. **本番環境では詳細なエラー情報を隠すことを推奨**
4. **エラー監視サービス（Sentry等）との連携を検討**

このError Boundaryを使用することで、アプリケーション全体がクラッシュすることなく、ユーザーフレンドリーなエラー表示ができます。

ReactのError Boundaryの実装方法をご説明します。

## 1. クラスベースのError Boundary

```jsx
import React from 'react';

class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null, errorInfo: null };
  }

  static getDerivedStateFromError(error) {
    // エラーが発生した時にstateを更新して、フォールバックUIを表示
    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    // エラー詳細をstateに保存し、エラーログサービスに送信することも可能
    this.setState({
      error: error,
      errorInfo: errorInfo
    });

    // エラーログサービスに送信（例：Sentry）
    console.error('Error Boundary caught an error:', error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="error-boundary">
          <h2>問題が発生しました</h2>
          <p>申し訳ございません。予期しないエラーが発生しました。</p>
          {process.env.NODE_ENV === 'development' && (
            <details style={{ whiteSpace: 'pre-wrap' }}>
              <summary>エラー詳細（開発環境のみ）</summary>
              <p>{this.state.error && this.state.error.toString()}</p>
              <p>{this.state.errorInfo.componentStack}</p>
            </details>
          )}
          <button 
            onClick={() => window.location.reload()}
            className="retry-button"
          >
            ページを再読み込み
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

export default ErrorBoundary;
```

## 2. より高機能なError Boundary

```jsx
import React from 'react';
import PropTypes from 'prop-types';

class AdvancedErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { 
      hasError: false, 
      error: null, 
      errorInfo: null,
      retryCount: 0
    };
  }

  static getDerivedStateFromError(error) {
    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    this.setState({
      error: error,
      errorInfo: errorInfo
    });

    // プロップスで渡されたエラーハンドラーを呼び出し
    if (this.props.onError) {
      this.props.onError(error, errorInfo);
    }
  }

  handleRetry = () => {
    const { maxRetries = 3 } = this.props;

    if (this.state.retryCount < maxRetries) {
      this.setState(prevState => ({
        hasError: false,
        error: null,
        errorInfo: null,
        retryCount: prevState.retryCount + 1
      }));
    }
  };

  render() {
    if (this.state.hasError) {
      // カスタムフォールバックUIがある場合は使用
      if (this.props.fallback) {
        return this.props.fallback(this.state.error, this.handleRetry);
      }

      const { maxRetries = 3 } = this.props;
      const canRetry = this.state.retryCount < maxRetries;

      return (
        <div className="error-boundary-container">
          <div className="error-boundary-content">
            <h2>{this.props.title || 'エラーが発生しました'}</h2>
            <p>{this.props.message || '申し訳ございません。予期しないエラーが発生しました。'}</p>

            {canRetry && (
              <button 
                onClick={this.handleRetry}
                className="retry-button"
              >
                再試行 ({this.state.retryCount}/{maxRetries})
              </button>
            )}

            <button 
              onClick={() => window.location.href = '/'}
              className="home-button"
            >
              ホームに戻る
            </button>

            {process.env.NODE_ENV === 'development' && (
              <details className="error-details">
                <summary>エラー詳細</summary>
                <pre>{this.state.error?.stack}</pre>
              </details>
            )}
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

AdvancedErrorBoundary.propTypes = {
  children: PropTypes.node.isRequired,
  fallback: PropTypes.func,
  onError: PropTypes.func,
  title: PropTypes.string,
  message: PropTypes.string,
  maxRetries: PropTypes.number
};

export default AdvancedErrorBoundary;
```

## 3. 使用例

```jsx
import React from 'react';
import ErrorBoundary from './ErrorBoundary';
import AdvancedErrorBoundary from './AdvancedErrorBoundary';

// 基本的な使用方法
function App() {
  return (
    <ErrorBoundary>
      <Header />
      <MainContent />
      <Footer />
    </ErrorBoundary>
  );
}

// 高度な使用方法
function AdvancedApp() {
  const handleError = (error, errorInfo) => {
    // エラーログサービスに送信
    console.error('Caught by Error Boundary:', error);
  };

  const customFallback = (error, retry) => (
    <div className="custom-error">
      <h1>カスタムエラーUI</h1>
      <button onClick={retry}>もう一度試す</button>
    </div>
  );

  return (
    <AdvancedErrorBoundary
      onError={handleError}
      fallback={customFallback}
      title="アプリケーションエラー"
      message="システムで問題が発生しています。"
      maxRetries={5}
    >
      <Header />
      <MainContent />
      <Footer />
    </AdvancedErrorBoundary>
  );
}
```

