import { ErrorBoundary } from 'react-error-boundary';

function ErrorFallback({ error, resetErrorBoundary }) {
  return (
    <div role="alert" style={{ 
      padding: '20px', 
      border: '1px solid #ff6b6b', 
      borderRadius: '4px',
      backgroundColor: '#ffe0e0',
      margin: '20px'
    }}>
      <h2>何か問題が発生しました:</h2>
      <pre>{error.message}</pre>
      <button onClick={resetErrorBoundary}>再試行</button>
    </div>
  );
}

function MyApp() {
  return (
    <ErrorBoundary
      FallbackComponent={ErrorFallback}
      onError={(error, errorInfo) => {
        console.error('Error caught by boundary:', error);
        console.error('Error info:', errorInfo);
      }}
    >
      <MyComponent />
    </ErrorBoundary>
  );
}
```

## より高度なError Boundary

```jsx
import React from 'react';

class AdvancedErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      hasError: false,
      error: null,
      errorInfo: null,
      eventId: null
    };
  }

  static getDerivedStateFromError(error) {
    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    // エラー情報を状態に保存
    this.setState({
      error: error,
      errorInfo: errorInfo
    });

    // エラーレポート
    this.reportError(error, errorInfo);
  }

  reportError = (error, errorInfo) => {
    // ここで外部サービスにエラーを送信
    // 例: Sentry, LogRocket, Bugsnag など
    console.error('Reporting error:', {
      error: error.toString(),
      errorInfo: errorInfo,
      userAgent: navigator.userAgent,
      url: window.location.href,
      timestamp: new Date().toISOString(),
      userId: this.props.userId || 'anonymous'
    });
  };

  handleReset = () => {
    this.setState({
      hasError: false,
      error: null,
      errorInfo: null,
      eventId: null
    });
  };

  render() {
    if (this.state.hasError) {
      // プロダクション環境とデベロップメント環境で表示を分ける
      if (process.env.NODE_ENV === 'production') {
        return (
          <div className="error-boundary">
            <h1>申し訳ありません</h1>
            <p>予期しないエラーが発生しました。</p>
            <p>問題が継続する場合は、サポートにお問い合わせください。</p>
            <button onClick={this.handleReset}>
              ページをリロード
            </button>
          </div>
        );
      }

      // 開発環境では詳細なエラー情報を表示
      return (
        <div className="error-boundary-dev">
          <h2>Error Boundary - Development Mode</h2>
          <div>
            <h3>Error:</h3>
            <pre>{this.state.error.toString()}</pre>
          </div>
          <div>
            <h3>Component Stack:</h3>
            <pre>{this.state.errorInfo.componentStack}</pre>
          </div>
          <button onClick={this.handleReset}>
            Reset
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

export default AdvancedErrorBoundary;
```

## 使用例

```jsx
import React from 'react';
import ErrorBoundary from './ErrorBoundary';

// エラーを意図的に発生させるコンポーネント
function BuggyComponent() {
  const [shouldThrow, setShouldThrow] = React.useState(false);

  if (shouldThrow) {
    throw new Error('意図的なエラーです！');
  }

  return (
    <div>
      <h3>正常なコンポーネント</h3>
      <button onClick={() => setShouldThrow(true)}>
        エラーを発生させる
      </button>
    </div>
  );
}

function App() {
  return (
    <div>
      <h1>Error Boundary デモ</h1>

      <ErrorBoundary>
        <BuggyComponent />
      </ErrorBoundary>

      <ErrorBoundary>
        <div>
          <h3>別のセクション</h3>
          <p>このセクションは上記のエラーの影響を受けません</p>
        </div>
      </ErrorBoundary>
    </div>
  );
}

export default App;
```

## Error Boundaryの制限事項

Error Boundaryは以下のエラーはキャッチできません：

1. イベントハンドラー内のエラー
2. 非同期コード（setTimeout、Promise など）
3. サーバーサイドレンダリング中のエラー
4. Error Boundary自体で発生したエラー

これらのケースでは、try-catchブロックや他のエラーハンドリング手法を使用する必要があります。

```jsx
// イベントハンドラーのエラーハンドリング例
function ComponentWithEventHandler() {
  const handleClick = () => {
    try {
      // エラーが発生する可能性のあるコード
      throw new Error('イベントハンドラーでのエラー');
    } catch (error) {
      console.error('イベントハンドラーエラー:', error);
      // ユーザーに適切なフィードバックを提供
    }
  };

  return <button onClick={handleClick}>クリック</button>;
}
```

この実装により、アプリケーション全体がクラッシュすることを防ぎ、ユーザーに適切なエラー表示を提供できます。

