      <MyComponent />
    </ErrorBoundary>
  );
}
```

## 4. 使用例

```jsx
function App() {
  return (
    <div className="app">
      <h1>My App</h1>

      {/* 全体をラップ */}
      <ErrorBoundary>
        <Header />
        <main>
          {/* 特定のセクションのみをラップ */}
          <CustomErrorBoundary
            title="コンテンツの読み込みに失敗しました"
            fallback={(error, reset) => (
              <div>
                <p>コンテンツを表示できません</p>
                <button onClick={reset}>再読み込み</button>
              </div>
            )}
          >
            <ContentSection />
          </CustomErrorBoundary>
        </main>
        <Footer />
      </ErrorBoundary>
    </div>
  );
}
```

## 注意点

- Error Boundary は**同期的なエラー**のみをキャッチします
- 以下はキャッチできません：
  - Event handlers内のエラー
  - 非同期コード（setTimeout、Promise等）
  - Server-side rendering中のエラー
  - Error Boundary自体で発生するエラー

非同期エラーには別途 try-catch を使用してください。

