normal_texts:
Node.jsアプリのメモリリークを調査する方法について、段階的に説明します。

## 1. 基本的な監視とツール

### **プロセス監視**
```javascript
// メモリ使用量の定期監視
setInterval(() => {
  const usage = process.memoryUsage();
  console.log({
    rss: `${Math.round(usage.rss / 1024 / 1024)} MB`,
    heapUsed: `${Math.round(usage.heapUsed / 1024 / 1024)} MB`,
    heapTotal: `${Math.round(usage.heapTotal / 1024 / 1024)} MB`,
    external: `${Math.round(usage.external / 1024 / 1024)} MB`
  });
}, 5000);
```

### **Node.js内蔵ツール**
```bash
# ヒープダンプの生成
node --heapsnapshot-signal=SIGUSR2 app.js
# プロセスにシグナル送信でヒープダンプ作成
kill -USR2 <pid>

# V8のガベージコレクション情報を表示
node --trace-gc app.js
```

## 2. 専門的な調査ツール

### **Chrome DevTools**
```javascript
// inspector を有効にしてアプリを起動
// package.json
{
  "scripts": {
    "debug": "node --inspect app.js"
  }
}
```
Chrome で `chrome://inspect` にアクセスして接続

### **clinic.js**
```bash
npm install -g clinic

# 全体的なパフォーマンス分析
clinic doctor -- node app.js

# メモリ使用量詳細分析
clinic heapprofiler -- node app.js
```

### **0x**
```bash
npm install -g 0x

# プロファイリング実行
0x node app.js
```

## 3. ヒープダンプ分析

### **heapdump パッケージ**
```javascript
const heapdump = require('heapdump');

// 手動でヒープダンプ作成
app.get('/heapdump', (req, res) => {
  heapdump.writeSnapshot((err, filename) => {
    if (err) {
      res.status(500).send(err);
    } else {
      res.send(`Heap dump written to ${filename}`);
    }
  });
});

// 定期的なヒープダンプ
setInterval(() => {
  heapdump.writeSnapshot();
}, 60000); // 1分ごと
```

### **v8-profiler-next**
```javascript
const profiler = require('v8-profiler-next');
const fs = require('fs');

// プロファイリング開始
const title = 'memory-leak-investigation';
profiler.startProfiling(title, true);

// 一定時間後に停止
setTimeout(() => {
  const profile = profiler.stopProfiling(title);
  profile.export()
    .pipe(fs.createWriteStream(`profile-${Date.now()}.cpuprofile`))
    .on('finish', () => profile.delete());
}, 30000);
```

## 4. メモリリーク検出のコード例

### **リーク検出用ミドルウェア**
```javascript
class MemoryLeakDetector {
  constructor(threshold = 100) {
    this.threshold = threshold; // MB
    this.samples = [];
    this.startMonitoring();
  }

  startMonitoring() {
    setInterval(() => {
      const usage = process.memoryUsage();
      this.samples.push({
        timestamp: Date.now(),
        heapUsed: usage.heapUsed
      });

      // 直近10回のサンプルを保持
      if (this.samples.length > 10) {
        this.samples.shift();
      }

      this.detectLeak();
    }, 10000);
  }

  detectLeak() {
    if (this.samples.length < 5) return;

    const recent = this.samples.slice(-5);
    const isIncreasing = recent.every((sample, index) => {
      return index === 0 || sample.heapUsed > recent[index - 1].heapUsed;
    });

    const currentMB = recent[recent.length - 1].heapUsed / 1024 / 1024;

    if (isIncreasing && currentMB > this.threshold) {
      console.warn('🚨 Memory leak detected!', {
        currentUsage: `${Math.round(currentMB)} MB`,
        trend: 'increasing'
      });

      // アラート送信やヒープダンプ作成などの処理
      this.handleMemoryLeak();
    }
  }

  handleMemoryLeak() {
    // ヒープダンプ作成
    require('heapdump').writeSnapshot();

    // 必要に応じてアプリケーションの再起動など
  }
}

// 使用例
const detector = new MemoryLeakDetector(150); // 150MB threshold
```

## 5. 一般的なメモリリークのパターンと対策

### **イベントリスナーのリーク**
```javascript
// ❌ 悪い例
function addListener() {
  process.on('exit', () => {
    console.log('exiting');
  });
}

// ✅ 良い例
let exitListener;
function addListener() {
  if (exitListener) {
    process.removeListener('exit', exitListener);
  }
  exitListener = () => console.log('exiting');
  process.on('exit', exitListener);
}
```

### **クロージャによるリーク**
```javascript
// ❌ 悪い例
function createHandler() {
  const largeData = new Array(1000000).fill('data');

  return function(req, res) {
    res.send('Hello'); // largeDataは参照され続ける
  };
}

// ✅ 良い例
function createHandler() {
  return function(req, res) {
    res.send('Hello');
  };
}
```

## 6. 本番環境での監視

### **PM2 with monitoring**
```javascript
// ecosystem.config.js
module.exports = {
  apps: [{
    name: 'myapp',
    script: 'app.js',
    max_memory_restart: '300M', // メモリ制限でリスタート
    monitoring: false,
    instances: 1
  }]
};
```

### **カスタム監視関数**
```javascript
function setupMemoryMonitoring() {
  const warningThreshold = 200 * 1024 * 1024; // 200MB
  const criticalThreshold = 400 * 1024 * 1024; // 400MB

  setInterval(() => {
    const usage = process.memoryUsage();

    if (usage.heapUsed > criticalThreshold) {
      console.error('CRITICAL: Memory usage too high', usage);
      // アラート送信、ヒープダンプ作成等
    } else if (usage.heapUsed > warningThreshold) {
      console.warn('WARNING: High memory usage', usage);
    }
  }, 30000);
}
```

これらの方法を組み合わせることで、効果的にメモリリークを調査・対策できます。特に本番環境では予防的な監視が重要です。

Node.jsアプリのメモリリークを調査する方法について、段階的に説明します。

## 1. メモリリークの症状を確認

