## 5. よくあるメモリリークの原因と対策

### イベントリスナーの未削除
```javascript
// ❌ 悪い例
function badExample() {
  const eventEmitter = new EventEmitter();
  eventEmitter.on('data', (data) => {
    // 処理
  });
  // removeListenerを忘れがち
}

// ✅ 良い例
function goodExample() {
  const eventEmitter = new EventEmitter();
  const handler = (data) => {
    // 処理
  };

  eventEmitter.on('data', handler);

  // 適切なタイミングでリスナーを削除
  process.on('exit', () => {
    eventEmitter.removeListener('data', handler);
  });
}
```

### タイマーの未クリア
```javascript
// ❌ 悪い例
function createTimer() {
  return setInterval(() => {
    // 何かの処理
  }, 1000);
}

// ✅ 良い例
function createTimerProperly() {
  const timer = setInterval(() => {
    // 何かの処理
  }, 1000);

  // 適切なタイミングでクリア
  process.on('SIGINT', () => {
    clearInterval(timer);
  });

  return timer;
}
```

### グローバル変数への蓄積
```javascript
// ❌ 悪い例
let globalCache = [];

function addToCache(data) {
  globalCache.push(data); // 無制限に増加
}

// ✅ 良い例
class LimitedCache {
  constructor(maxSize = 1000) {
    this.cache = [];
    this.maxSize = maxSize;
  }

  add(data) {
    this.cache.push(data);
    if (this.cache.length > this.maxSize) {
      this.cache.shift(); // 古いデータを削除
    }
  }
}
```

## 6. 監視とアラートの設定

