  })
  .catch(error => {
    // どれか1つでも失敗すると実行
    console.error('エラー:', error);
  });
```

### Promise.race
- **最初に完了した Promise の結果を返す**
- 成功・失敗問わず、最も早い結果で決定

```javascript
const promises = [
  fetch('/api/fast'),
  fetch('/api/slow'),
  new Promise(resolve => setTimeout(() => resolve('timeout'), 5000))
];

Promise.race(promises)
  .then(result => {
    // 最も早く完了したもの
    console.log('最初の結果:', result);
  });
```

## 使い分け

### Promise.all を使う場面
- **複数の処理が全て必要**な場合
- データの並列取得
- 全ての前処理完了後に次の処理を実行

### Promise.race を使う場面
- **タイムアウト処理**
- 複数のサーバーから最速レスポンスを取得
- キャンセル可能な処理の実装

```javascript
// タイムアウト例
const timeoutPromise = new Promise((_, reject) => 
  setTimeout(() => reject(new Error('Timeout')), 3000)
);

Promise.race([fetch('/api/data'), timeoutPromise])
  .then(response => console.log('成功'))
  .catch(error => console.log('タイムアウトまたはエラー'));
```

## Promise.allとPromise.raceの違い

### Promise.all
**すべてのPromiseが完了するまで待つ**

```javascript
const promise1 = new Promise(resolve => setTimeout(() => resolve('結果1'), 1000));
const promise2 = new Promise(resolve => setTimeout(() => resolve('結果2'), 2000));
const promise3 = new Promise(resolve => setTimeout(() => resolve('結果3'), 1500));

Promise.all([promise1, promise2, promise3])
  .then(results => {
    console.log(results); // ['結果1', '結果2', '結果3'] (2秒後に実行)
  });
```

### Promise.race
**最初に完了したPromiseで決定される**

```javascript
Promise.race([promise1, promise2, promise3])
  .then(result => {
    console.log(result); // '結果1' (1秒後に実行)
  });
```

## 使い分け

### Promise.allを使う場面
- **複数のAPIを並行取得**して、すべての結果が必要な場合
- **関連するリソース**を同時に読み込む場合

```javascript
// すべてのデータが揃ってから画面表示
const [users, posts, comments] = await Promise.all([
  fetchUsers(),
  fetchPosts(), 
  fetchComments()
]);
```

### Promise.raceを使う場面
- **タイムアウト処理**を実装する場合
- **最速のサーバー**から結果を取得したい場合

```javascript
// 3秒でタイムアウト
const result = await Promise.race([
  fetchData(),
  new Promise((_, reject) => 
    setTimeout(() => reject(new Error('Timeout')), 3000)
  )
]);
```

## エラーハンドリングの違い
- **Promise.all**: 1つでもrejectされると全体が失敗
- **Promise.race**: 最初に完了した結果（成功/失敗）で決まる

## Promise.allとPromise.raceの基本的な違い

### Promise.all
- **すべて**のPromiseが成功するまで待機
- 1つでも失敗すると即座に失敗
- 結果は元の順序で配列として返される

```javascript
const promise1 = fetch('/api/user');
const promise2 = fetch('/api/posts');
const promise3 = fetch('/api/comments');

Promise.all([promise1, promise2, promise3])
  .then(responses => {
    // 3つすべて成功時の処理
    console.log('すべてのAPIが完了');
  })
  .catch(error => {
    // 1つでも失敗した場合
    console.log('いずれかのAPIが失敗');
  });
```

### Promise.race
- **最初に完了**したPromiseの結果を返す
- 成功・失敗に関わらず、最初に決着がついたものが結果

```javascript
const timeout = new Promise((_, reject) => 
  setTimeout(() => reject('タイムアウト'), 5000)
);
const apiCall = fetch('/api/data');

Promise.race([apiCall, timeout])
  .then(response => {
    console.log('APIが時間内に完了');
  })
  .catch(error => {
    console.log('タイムアウトまたはAPIエラー');
  });
```

## 使い分けの場面

### Promise.allを使う場面
- 複数のデータを並行取得して、すべて必要な場合
- 依存関係のない複数の処理を効率的に実行

### Promise.raceを使う場面
- タイムアウト処理の実装
- 複数のサーバーから最速のレスポンスを取得
