class ConfigurableRateLimit:
    def __init__(self, redis_client):
        self.redis = redis_client
        self.rules = {}

    def add_rule(self, pattern, limit, window, identifier='ip'):
        self.rules[pattern] = {
            'limit': limit,
            'window': window,
            'identifier': identifier
        }

    def check_request(self, path, ip, user_id=None):
        for pattern, rule in self.rules.items():
            if self._match_pattern(path, pattern):
                key = self._get_key(rule['identifier'], ip, user_id, pattern)
                return self._check_limit(key, rule['limit'], rule['window'])
        return True

    def _get_key(self, identifier, ip, user_id, pattern):
        if identifier == 'ip':
            return f"rl:ip:{ip}:{pattern}"
        elif identifier == 'user' and user_id:
            return f"rl:user:{user_id}:{pattern}"
        return f"rl:global:{pattern}"
